"use client";

import { useEffect, useRef, useState } from "react";
import { AudioLines, Bot, LoaderCircle, Mic, Send, ShieldCheck, Sparkles, Square, Volume2 } from "lucide-react";
import { create_budget } from "@/lib/financial-tools";
import { executeFinancialTool, selectFinancialTool } from "@/lib/financial-agent";
import { formatMoney } from "@/lib/finance";
import type { Budget, Investment, Transaction, UpcomingBill } from "@/lib/models";
import type { FinancialToolName } from "@/lib/financial-agent";

interface ChatMessage {
  id: string;
  role: "assistant" | "user";
  text: string;
  verifiedAnswer?: string;
  tool?: FinancialToolName;
  audioUrl?: string;
}

interface FinancialAgentProps {
  transactions: Transaction[];
  currency: string;
  budgets: Budget[];
  investments: Investment[];
  bills: UpcomingBill[];
  onCreateBudgets: (values: Budget[]) => Promise<void>;
}

const suggestedQuestions = [
  "How much did I spend this month?",
  "Where does most of my money go?",
  "How can I save CHF 500 monthly?",
  "Create a budget for next month.",
  "Will I have enough money in 30 days?",
  "Explain my investment portfolio.",
  "Which recurring payments should I review?"
];

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function numberValue(value: unknown) {
  return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

function stringValue(value: unknown, fallback = "") {
  return typeof value === "string" ? value : fallback;
}

function listValue(value: unknown): unknown[] {
  return Array.isArray(value) ? value : [];
}

function isBudget(value: unknown): value is Budget {
  return isRecord(value)
    && typeof value.id === "string"
    && typeof value.category === "string"
    && typeof value.monthlyLimit === "number"
    && typeof value.actualSpending === "number";
}

function formatToolAnswer(tool: FinancialToolName, value: unknown, currency: string) {
  if (tool === "get_recurring_payments" || tool === "get_savings_opportunities") {
    const items = listValue(value).filter(isRecord);
    if (!items.length) return tool === "get_recurring_payments"
      ? "No recurring-payment pattern met the minimum evidence threshold in the imported transactions."
      : "No savings opportunity met the current evidence thresholds. Importing more history may reveal additional patterns.";
    return items.slice(0, 4).map((item) => {
      if (tool === "get_recurring_payments") {
        return `${stringValue(item.name, "Payment")}: about ${formatMoney(numberValue(item.monthlyAmount), currency)} per month (${stringValue(item.cadence)} pattern, ${numberValue(item.occurrenceCount)} observations).`;
      }
      return `${stringValue(item.title, "Opportunity")}: estimated ${formatMoney(numberValue(item.monthlySavings), currency)} per month. Assumption: ${stringValue(item.assumption, "Illustrative only.")}`;
    }).join("\n");
  }

  const data = isRecord(value) ? value : {};
  switch (tool) {
    case "get_financial_summary":
      return `Across ${numberValue(data.monthsAnalyzed)} imported month(s), recorded income was ${formatMoney(numberValue(data.income), currency)}, expenses were ${formatMoney(numberValue(data.expenses), currency)}, and net cash flow was ${formatMoney(numberValue(data.netCashFlow), currency)}. Average monthly savings were ${formatMoney(numberValue(data.monthlySavings), currency)} (${Math.round(numberValue(data.savingsRate) * 100)}%). A confirmed account balance is not available from transaction data.`;
    case "get_monthly_spending":
      return `${stringValue(data.month, "The latest imported month")}: net consumer expenses were ${formatMoney(numberValue(data.netExpenses), currency)} after ${formatMoney(numberValue(data.refunds), currency)} in refunds. Recorded income was ${formatMoney(numberValue(data.income), currency)}; transfers are excluded.`;
    case "get_spending_by_category": {
      const categories = listValue(data.categories).filter(isRecord).slice(0, 5);
      return categories.length
        ? `Spending by category for ${stringValue(data.month, "the latest imported month")}:\n${categories.map((item) => `${stringValue(item.name, "Other")}: ${formatMoney(numberValue(item.value), currency)}`).join("\n")}`
        : "There is no category-level expense data for the latest imported month.";
    }
    case "create_budget": {
      const budgets = listValue(data.budgets).filter(isRecord);
      if (!budgets.length) return `There are no new category limits to create for ${stringValue(data.targetMonth, "next month")}. Existing limits are left unchanged.`;
      return `I saved a suggested budget for ${stringValue(data.targetMonth, "next month")}:\n${budgets.map((item) => `${stringValue(item.category, "Other")}: ${formatMoney(numberValue(item.monthlyLimit), currency)} monthly`).join("\n")}\n${stringValue(data.assumptions)}`;
    }
    case "get_budget_status": {
      const statuses = listValue(data.budgets).filter(isRecord);
      return statuses.length
        ? `Budget status for ${stringValue(data.month, "the latest imported month")}:\n${statuses.map((item) => `${stringValue(item.category, "Category")}: ${formatMoney(numberValue(item.actualSpending), currency)} of ${formatMoney(numberValue(item.monthlyLimit), currency)}${item.isOverBudget === true ? `, ${formatMoney(numberValue(item.overspent), currency)} over` : `, ${formatMoney(numberValue(item.remaining), currency)} remaining`}`).join("\n")}`
        : "No saved budget limits are available for this currency.";
    }
    case "get_cashflow_forecast": {
      const horizons = listValue(data.horizons).filter(isRecord);
      if (!horizons.length) return "There is not enough imported information to produce a cash-flow estimate.";
      return `Estimated net flow (not a balance):\n${horizons.map((item) => `${numberValue(item.days)} days: income ${formatMoney(numberValue(item.projectedIncome), currency)}, expenses ${formatMoney(numberValue(item.projectedExpenses), currency)}, net ${formatMoney(numberValue(item.projectedNetFlow), currency)}; known bills ${formatMoney(numberValue(item.knownBills), currency)}.`).join("\n")}\n${listValue(data.assumptions).filter((item): item is string => typeof item === "string").join(" ")}`;
    }
    case "get_investment_portfolio":
    case "calculate_investment_performance":
      return `Manually priced portfolio in ${currency}: invested ${formatMoney(numberValue(data.totalInvested), currency)}, current entered value ${formatMoney(numberValue(data.currentValue), currency)}, unrealised change ${formatMoney(numberValue(data.unrealizedProfitLoss), currency)} (${numberValue(data.returnPercent).toFixed(2)}%). These values use user-entered prices, not live market data.`;
    case "get_recurring_payments":
    case "get_savings_opportunities":
      return "";
  }
}

function minimizeForProvider(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(minimizeForProvider);
  if (!isRecord(value)) return value;
  return Object.fromEntries(Object.entries(value)
    .filter(([key]) => !["id", "transactionIds", "account", "sourceFile"].includes(key))
    .map(([key, child]) => [key, minimizeForProvider(child)]));
}

export function FinancialAgent({ transactions, currency, budgets, investments, bills, onCreateBudgets }: FinancialAgentProps) {
  const [question, setQuestion] = useState("");
  const [messages, setMessages] = useState<ChatMessage[]>([{
    id: "welcome",
    role: "assistant",
    text: "Hello. I’m the PostFinance Financial Intelligence Agent, an independent prototype. I can answer with calculations from your imported activity. Your exact figures stay on this device unless you explicitly enable AI sharing."
  }]);
  const [sharingConsent, setSharingConsent] = useState(false);
  const [busy, setBusy] = useState(false);
  const [recording, setRecording] = useState(false);
  const [transcribing, setTranscribing] = useState(false);
  const [voiceBusy, setVoiceBusy] = useState(false);
  const [error, setError] = useState("");
  const recorderRef = useRef<MediaRecorder | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const audioChunks = useRef<Blob[]>([]);
  const audioUrls = useRef<string[]>([]);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const audioElements = useRef(new Map<string, HTMLAudioElement>());

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth", block: "end" });
  }, [messages, busy, transcribing]);

  useEffect(() => () => {
    if (recorderRef.current?.state === "recording") {
      recorderRef.current.onstop = null;
      recorderRef.current.stop();
    }
    streamRef.current?.getTracks().forEach((track) => track.stop());
    audioUrls.current.forEach((url) => URL.revokeObjectURL(url));
  }, []);

  async function submitQuestion(rawQuestion: string, fromVoice = false) {
    const prompt = rawQuestion.trim().slice(0, 1000);
    if (!prompt || busy) return;
    setBusy(true);
    setError("");
    setQuestion("");
    const userMessage: ChatMessage = { id: crypto.randomUUID(), role: "user", text: prompt };
    const responseId = crypto.randomUUID();
    setMessages((current) => [...current, userMessage]);

    try {
      const tool = selectFinancialTool(prompt);
      const context = { transactions, currency, budgets, investments, bills };
      const result = tool === "create_budget"
        ? create_budget(transactions, currency, budgets)
        : executeFinancialTool(tool, context);
      if (tool === "create_budget" && isRecord(result) && Array.isArray(result.budgets)) {
        await onCreateBudgets(result.budgets.filter(isBudget));
      }
      const verifiedAnswer = formatToolAnswer(tool, result, currency);
      let explanation = "I used the local deterministic calculation. Exact figures are shown below.";

      if (sharingConsent) {
        try {
          const response = await fetch("/api/agent/respond", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              consent: true,
              question: prompt,
              tool,
              toolResult: JSON.stringify(minimizeForProvider(result))
            })
          });
          const payload = await response.json() as { explanation?: string; error?: string };
          if (!response.ok) throw new Error(payload.error || "The language model is unavailable.");
          explanation = payload.explanation || explanation;
        } catch (reason) {
          setError(reason instanceof Error ? `${reason.message} Using the verified local answer instead.` : "The language model is unavailable. Using the verified local answer instead.");
        }
      }

      const assistantMessage: ChatMessage = {
        id: responseId,
        role: "assistant",
        text: explanation,
        verifiedAnswer,
        tool
      };
      setMessages((current) => [...current, assistantMessage]);
      if (fromVoice) void synthesizeSpeech(responseId, `${explanation} ${verifiedAnswer}`, true);
    } catch (reason) {
      setMessages((current) => [...current, {
        id: responseId,
        role: "assistant",
        text: reason instanceof Error ? `I couldn’t complete that action: ${reason.message}` : "I couldn’t complete that action. Please try again."
      }]);
    } finally {
      setBusy(false);
    }
  }

  async function transcribeRecording(blob: Blob) {
    setTranscribing(true);
    setError("");
    try {
      const form = new FormData();
      form.append("file", blob, "recording.webm");
      const response = await fetch("/api/voice/transcribe", { method: "POST", body: form });
      const payload = await response.json() as { text?: string; error?: string };
      if (!response.ok || !payload.text) throw new Error(payload.error || "Transcription failed.");
      setQuestion(payload.text);
      await submitQuestion(payload.text, true);
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Voice transcription failed. You can type your question instead.");
    } finally {
      setTranscribing(false);
    }
  }

  async function startRecording() {
    setError("");
    if (!navigator.mediaDevices?.getUserMedia || typeof MediaRecorder === "undefined") {
      setError("Audio recording is not supported in this browser. You can type your question instead.");
      return;
    }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      audioChunks.current = [];
      const mimeType = ["audio/webm;codecs=opus", "audio/webm", "audio/mp4"].find((type) => MediaRecorder.isTypeSupported(type));
      const recorder = new MediaRecorder(stream, mimeType ? { mimeType } : undefined);
      recorderRef.current = recorder;
      recorder.ondataavailable = (event) => {
        if (event.data.size) audioChunks.current.push(event.data);
      };
      recorder.onstop = () => {
        stream.getTracks().forEach((track) => track.stop());
        streamRef.current = null;
        const audio = new Blob(audioChunks.current, { type: recorder.mimeType || "audio/webm" });
        if (audio.size > 10 * 1024 * 1024) {
          setError("This recording is over the 10 MB limit. Please record a shorter question.");
          return;
        }
        void transcribeRecording(audio);
      };
      recorder.start();
      setRecording(true);
    } catch (reason) {
      streamRef.current?.getTracks().forEach((track) => track.stop());
      streamRef.current = null;
      const permissionDenied = reason instanceof DOMException && reason.name === "NotAllowedError";
      setError(permissionDenied
        ? "Microphone permission was denied. Allow microphone access or type your question."
        : "The microphone could not be started. You can type your question instead.");
    }
  }

  function stopRecording() {
    if (recorderRef.current?.state === "recording") recorderRef.current.stop();
    setRecording(false);
  }

  async function synthesizeSpeech(messageId: string, text: string, autoPlay = false) {
    setVoiceBusy(true);
    setError("");
    try {
      const response = await fetch("/api/voice/speak", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ text: text.slice(0, 4000) })
      });
      if (!response.ok) {
        const payload = await response.json() as { error?: string };
        throw new Error(payload.error || "Speech generation failed.");
      }
      const url = URL.createObjectURL(await response.blob());
      audioUrls.current.push(url);
      setMessages((current) => current.map((message) => message.id === messageId ? { ...message, audioUrl: url } : message));
      if (autoPlay) {
        window.setTimeout(() => {
          void audioElements.current.get(messageId)?.play().catch(() => {
            setError("Audio is ready. Press Play to hear the response.");
          });
        }, 100);
      }
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Speech generation failed. The text response is still available.");
    } finally {
      setVoiceBusy(false);
    }
  }

  function submitForm(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    void submitQuestion(question);
  }

  return (
    <>
      <div className="mb-6">
        <p className="mb-1 text-[11px] font-bold uppercase tracking-[0.15em] text-brand">Personal financial intelligence</p>
        <h1 className="text-2xl font-semibold tracking-tight text-ink sm:text-[28px]">PostFinance Financial Intelligence Agent</h1>
        <p className="mt-1.5 text-sm text-slate-500">A turn-based voice and text assistant grounded in your locally calculated transaction data.</p>
      </div>
      <section className="mx-auto max-w-4xl overflow-hidden rounded-2xl border border-line bg-white shadow-card">
        <header className="flex items-center gap-3 border-b border-slate-100 bg-slate-50/70 px-4 py-4 sm:px-5">
          <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-brand text-white"><AudioLines size={19} /></span>
          <div><p className="text-sm font-semibold text-ink">Financial Intelligence Agent</p><p className="text-[11px] text-slate-400">Local calculations · Not financial advice</p></div>
          <span className="ml-auto hidden items-center gap-1.5 rounded-full bg-emerald-50 px-2.5 py-1.5 text-[10px] font-semibold text-emerald-700 sm:flex"><ShieldCheck size={13} /> Private by default</span>
        </header>

        <div aria-live="polite" className="max-h-[560px] min-h-[330px] space-y-4 overflow-y-auto p-4 sm:p-6">
          {messages.map((message) => (
            <div className={`flex ${message.role === "user" ? "justify-end" : "justify-start"}`} key={message.id}>
              <article className={`max-w-[94%] rounded-2xl px-4 py-3 sm:max-w-[88%] ${message.role === "user" ? "rounded-br-md bg-ink text-white" : "rounded-bl-md bg-slate-100 text-ink"}`}>
                <div className="mb-1.5 flex items-center gap-2 text-[10px] font-semibold opacity-70">{message.role === "user" ? "You" : <><Bot size={12} /> Financial agent</>}</div>
                <p className="whitespace-pre-line text-sm leading-6">{message.text}</p>
                {message.verifiedAnswer && <div className="mt-3 whitespace-pre-line rounded-xl border border-slate-200/80 bg-white p-3 text-xs leading-5 text-slate-700"><p className="mb-1 flex items-center gap-1.5 text-[10px] font-bold uppercase tracking-wide text-emerald-700"><ShieldCheck size={12} /> Verified local calculation · {message.tool?.replaceAll("_", " ")}</p>{message.verifiedAnswer}</div>}
                {message.role === "assistant" && message.verifiedAnswer && (
                  <div className="mt-3">
                    {message.audioUrl
                      ? <audio className="h-9 max-w-full" controls preload="none" ref={(element) => {if (element) audioElements.current.set(message.id, element); else audioElements.current.delete(message.id);}} src={message.audioUrl} />
                      : <button className="inline-flex items-center gap-1.5 text-[11px] font-semibold text-slate-500 hover:text-brand disabled:opacity-50" disabled={voiceBusy} onClick={() => void synthesizeSpeech(message.id, `${message.text} ${message.verifiedAnswer}`)} type="button"><Volume2 size={14} /> {voiceBusy ? "Preparing audio…" : "Play response"}</button>}
                  </div>
                )}
              </article>
            </div>
          ))}
          {(busy || transcribing) && <div className="flex justify-start"><div className="flex items-center gap-2 rounded-xl bg-slate-100 px-4 py-3 text-xs text-slate-500"><LoaderCircle className="animate-spin" size={14} />{transcribing ? "Transcribing audio…" : "Checking your financial data…"}<span className="animate-pulse">•••</span></div></div>}
          <div ref={chatEndRef} />
        </div>

        <div className="border-t border-slate-100 p-4 sm:p-5">
          {error && <p className="mb-3 rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-xs leading-5 text-amber-800" role="alert">{error}</p>}
          <div className="mb-3 flex items-start gap-2 rounded-xl bg-slate-50 p-3">
            <input checked={sharingConsent} className="mt-0.5 accent-[#d92e3a]" id="agent-sharing-consent" onChange={(event) => setSharingConsent(event.target.checked)} type="checkbox" />
            <label className="text-[11px] leading-5 text-slate-500" htmlFor="agent-sharing-consent">Optional: allow this question and its minimal, calculated result (never your CSV or transaction list) to be sent to the configured AI provider for an explanation. Unchecked answers stay local.</label>
          </div>
          {recording && <p className="mb-2 flex items-center gap-2 text-xs font-medium text-red-600"><span className="h-2 w-2 animate-pulse rounded-full bg-red-500" /> Recording · click Stop when you’re done</p>}
          <form className="flex gap-2" onSubmit={submitForm}>
            {recording
              ? <button aria-label="Stop recording" className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-red-50 text-red-600" onClick={stopRecording} type="button"><Square size={17} fill="currentColor" /></button>
              : <button aria-label="Start voice recording" className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl border border-slate-200 text-slate-500 hover:bg-slate-50 disabled:opacity-50" disabled={busy || transcribing} onClick={() => void startRecording()} type="button"><Mic size={17} /></button>}
            <input aria-label="Ask the financial agent" className="min-w-0 flex-1 rounded-xl border border-slate-200 px-4 text-sm outline-none focus:border-brand disabled:bg-slate-50" disabled={busy || transcribing || recording} maxLength={1000} onChange={(event) => setQuestion(event.target.value)} onKeyDown={(event) => {if (event.key === "Enter" && !event.shiftKey) {event.preventDefault();void submitQuestion(question);}}} placeholder={recording ? "Recording…" : "Ask about spending, savings, a budget, or investments"} value={question} />
            <button aria-label="Send question" className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-brand text-white hover:bg-rose-700 disabled:opacity-50" disabled={busy || transcribing || !question.trim()} type="submit"><Send size={16} /></button>
          </form>
          <p className="mt-2 text-[10px] leading-4 text-slate-400">Voice is turn-based, not full-duplex. Recordings are sent to ElevenLabs for transcription; you can always use text instead. No financial fact is inferred from speech alone.</p>
          <div className="mt-3 flex flex-wrap gap-2">{suggestedQuestions.map((item) => <button className="rounded-full border border-slate-200 px-3 py-1.5 text-[10px] text-slate-500 hover:border-slate-300 hover:text-ink disabled:opacity-50" disabled={busy || transcribing} key={item} onClick={() => void submitQuestion(item)} type="button"><Sparkles className="mr-1 inline" size={11} />{item}</button>)}</div>
        </div>
      </section>
    </>
  );
}
